From 1ffff57e44a4a507786f5626070d9b1f3e371389 Mon Sep 17 00:00:00 2001
From: Juliusz Chroboczek <jch@irif.fr>
Date: Fri, 11 May 2018 14:13:06 +0200
Subject: [PATCH] Fix parsing of source length in filters.

This fixes a bug that was introduced in commit 4f4e3cb, and prevented
non-source-specific IPv4 routes from being redistributed.  Thanks
to Niklas Yann Wettengel for the detective work.

diff --git a/configuration.c b/configuration.c
index 449e580..5f52ecb 100644
--- a/configuration.c
+++ b/configuration.c
@@ -479,10 +479,14 @@ parse_filter(int c, gnc_t gnc, void *closure, struct filter **filter_return)
            filter->src_plen_le < 128 || filter->src_plen_ge > 0)
             filter->af = AF_INET6;
     } else if(filter->af == AF_INET) {
-        filter->plen_le += 96;
-        filter->plen_ge += 96;
-        filter->src_plen_le += 96;
-        filter->src_plen_ge += 96;
+        if(filter->plen_le < 128)
+            filter->plen_le += 96;
+        if(filter->plen_ge > 0)
+            filter->plen_ge += 96;
+        if(filter->src_plen_le < 128)
+            filter->src_plen_le += 96;
+        if(filter->src_plen_ge > 0)
+            filter->src_plen_ge += 96;
     }
     *filter_return = filter;
     return c;
-- 
2.25.1

        You will be given the root cause of a bug, the commit message and the corresponding patch.
        You need to extract all code statements that lead to the bug from the patch, based on the root cause and the commit message.

        Root cause:
        The bug was caused by unconditionally adding 96 to the prefix length fields (`plen_le`, `plen_ge`, `src_plen_le`, `src_plen_ge`) in the `parse_filter` function, which could lead to incorrect values for non-source-specific IPv4 routes, preventing them from being redistributed properly. The lack of conditional checks allowed invalid configurations to be set, affecting the routing behavior.

        Commit message:
        Fix parsing of source length in filters.

This fixes a bug that was introduced in commit 4f4e3cb, and prevented
non-source-specific IPv4 routes from being redistributed.  Thanks
to Niklas Yann Wettengel for the detective work.  

        Patch:

 static int
 parse_filter(int c, gnc_t gnc, void *closure, struct filter **filter_return)
 {
     char *token;
     struct filter *filter;

     filter = calloc(1, sizeof(struct filter));
     if(filter == NULL)
         return -2;
     filter->plen_le = 128;
     filter->src_plen_le = 128;

     while(1) {
         c = skip_whitespace(c, gnc, closure);
         if(c < 0 || c == '\n' || c == '#') {
             c = skip_to_eol(c, gnc, closure);
             break;
         }
         c = getword(c, &token, gnc, closure);
         if(c < -1) {
             free_filter(filter);
             return -2;
         }

         if(strcmp(token, "ip") == 0) {
             int af;
             c = getnet(c, &filter->prefix, &filter->plen, &af,
                        gnc, closure);
             if(c < -1)
                 goto error;
             if(filter->af == AF_UNSPEC)
                 filter->af = af;
             else if(filter->af != af)
                 goto error;
         } else if(strcmp(token, "src-ip") == 0) {
             int af;
             c = getnet(c, &filter->src_prefix, &filter->src_plen, &af,
                        gnc, closure);
             if(c < -1)
                 goto error;
             if(filter->af == AF_UNSPEC)
                 filter->af = af;
             else if(filter->af != af)
                 goto error;
         } else if(strcmp(token, "eq") == 0) {
             int p;
             c = getint(c, &p, gnc, closure);
             if(c < -1)
                 goto error;
             filter->plen_ge = MAX(filter->plen_ge, p);
             filter->plen_le = MIN(filter->plen_le, p);
         } else if(strcmp(token, "le") == 0) {
             int p;
             c = getint(c, &p, gnc, closure);
             if(c < -1)
                 goto error;
             filter->plen_le = MIN(filter->plen_le, p);
         } else if(strcmp(token, "ge") == 0) {
             int p;
             c = getint(c, &p, gnc, closure);
             if(c < -1)
                 goto error;
             filter->plen_ge = MAX(filter->plen_ge, p);
         } else if(strcmp(token, "src-eq") == 0) {
             int p;
             c = getint(c, &p, gnc, closure);
             if(c < -1)
                 goto error;
             filter->src_plen_ge = MAX(filter->src_plen_ge, p);
             filter->src_plen_le = MIN(filter->src_plen_le, p);
         } else if(strcmp(token, "src-le") == 0) {
             int p;
             c = getint(c, &p, gnc, closure);
             if(c < -1)
                 goto error;
             filter->src_plen_le = MIN(filter->src_plen_le, p);
         } else if(strcmp(token, "src-ge") == 0) {
             int p;
             c = getint(c, &p, gnc, closure);
             if(c < -1)
                 goto error;
             filter->src_plen_ge = MAX(filter->src_plen_ge, p);
         } else if(strcmp(token, "neigh") == 0) {
             unsigned char *neigh = NULL;
             c = getip(c, &neigh, NULL, gnc, closure);
             if(c < -1)
                 goto error;
             filter->neigh = neigh;
         } else if(strcmp(token, "id") == 0) {
             unsigned char *id = NULL;
             c = getid(c, &id, gnc, closure);
             if(c < -1)
                 goto error;
             filter->id = id;
         } else if(strcmp(token, "proto") == 0) {
             int proto;
             c = getint(c, &proto, gnc, closure);
             if(c < -1)
                 goto error;
             filter->proto = proto;
         } else if(strcmp(token, "local") == 0) {
             filter->proto = RTPROT_BABEL_LOCAL;
         } else if(strcmp(token, "if") == 0) {
             char *interface;
             c = getstring(c, &interface, gnc, closure);
             if(c < -1)
                 goto error;
             filter->ifname = interface;
             filter->ifindex = if_nametoindex(interface);
         } else if(strcmp(token, "allow") == 0) {
             filter->action.add_metric = 0;
         } else if(strcmp(token, "deny") == 0) {
             filter->action.add_metric = INFINITY;
         } else if(strcmp(token, "metric") == 0) {
             int metric;
             c = getint(c, &metric, gnc, closure);
             if(c < -1) goto error;
             if(metric <= 0 || metric > INFINITY)
                 goto error;
             filter->action.add_metric = metric;
         } else if(strcmp(token, "src-prefix") == 0) {
             int af;
             c = getnet(c, &filter->action.src_prefix, &filter->action.src_plen,
                        &af, gnc, closure);
             if(c < -1)
                 goto error;
             if(filter->af == AF_UNSPEC)
                 filter->af = af;
             else if(filter->af != af)
                 goto error;
         } else if(strcmp(token, "table") == 0) {
             int table;
             c = getint(c, &table, gnc, closure);
             if(c < -1) goto error;
             if(table <= 0 || table > INFINITY)
                 goto error;
             filter->action.table = table;
         } else {
             goto error;
         }
         free(token);
     }
     if(filter->af == 0) {
         if(filter->plen_le < 128 || filter->plen_ge > 0 ||
            filter->src_plen_le < 128 || filter->src_plen_ge > 0)
             filter->af = AF_INET6;
     } else if(filter->af == AF_INET) {
-        filter->plen_le += 96;
-        filter->plen_ge += 96;
-        filter->src_plen_le += 96;
-        filter->src_plen_ge += 96;
+        if(filter->plen_le < 128)
+            filter->plen_le += 96;
+        if(filter->plen_ge > 0)
+            filter->plen_ge += 96;
+        if(filter->src_plen_le < 128)
+            filter->src_plen_le += 96;
+        if(filter->src_plen_ge > 0)
+            filter->src_plen_ge += 96;
     }
     *filter_return = filter;
     return c;

  error:
     free(token);
     free_filter(filter);
     return -2;
 }



